mapper.select:
SELECT id, type, status, remark, create_time, end_time, is_deleted
FROM conversation 
WHERE id = #{id}

mapper.update:
UPDATE conversation
type = #{type}, status = #{status}, remark = #{remark}, end_time = #{endTime}, is_deleted = #{isDeleted},
WHERE id = #{id}

mapper.select:
SELECT c.id, c.status, c.create_time AS createTime, c.end_time AS endTime, c.remark, u.id AS userId, u.name AS userName, u.phone AS userPhone, u.avatar AS userAvatar, a.id AS adminId, a.name AS adminName, (SELECT content FROM conversation_message WHERE conversation_id = c.id AND is_deleted = 0 ORDER BY send_time DESC LIMIT 1) AS lastMessage, (SELECT send_time FROM conversation_message WHERE conversation_id = c.id AND is_deleted = 0 ORDER BY send_time DESC LIMIT 1) AS lastMessageTime, (SELECT COUNT(*) FROM conversation_message WHERE conversation_id = c.id AND is_deleted = 0) AS messageCount, IFNULL(cp_admin.unread_count, 0) AS unreadCount FROM conversation c LEFT JOIN conversation_participant cp_user ON c.id = cp_user.conversation_id AND cp_user.participant_type = 0 AND cp_user.role = 0 AND cp_user.is_deleted = 0 LEFT JOIN user_info u ON cp_user.participant_id = u.id LEFT JOIN conversation_participant cp_admin ON c.id = cp_admin.conversation_id AND cp_admin.participant_type = 1 AND cp_admin.role = 1 AND cp_admin.is_deleted = 0 LEFT JOIN admin_info a ON cp_admin.participant_id = a.id WHERE c.type = 0 AND c.is_deleted = 0
AND c.status = #{query.status}
AND u.id = #{query.userId}
AND a.id = #{query.adminId}
AND c.create_time >= #{query.startTime}
AND c.create_time <= #{query.endTime}
AND EXISTS ( SELECT 1 FROM conversation_message cm WHERE cm.conversation_id = c.id AND cm.content LIKE CONCAT('%', #{query.keyword}, '%') AND cm.is_deleted = 0 )
ORDER BY c.create_time DESC
